        // 기본 타입: == 는 값 비교
        int a = 10;
        int b = 10;
        System.out.println("a == b: " + (a == b));  // true

        // 참조 타입: == 는 주소 비교!
        int[] arr1 = {1, 2, 3};
        int[] arr2 = {1, 2, 3};
