public class SwapFail {
    public static void main(String[] args) {
        int[] a = {1, 2, 3};
        int[] b = {10, 20, 30};

        System.out.println("전: a[0]=" + a[0] + ", b[0]=" + b[0]);
        swap(a, b);
        System.out.println("후: a[0]=" + a[0] + ", b[0]=" + b[0]);
    }

    static void swap(int[] x, int[] y) {
        int[] temp = x;
        x = y;
        y = temp;
        // x, y 참조만 바뀜. a, b는 그대로!
    }
}

